-- ── story 1-6c: drug and FSSAI licences ─────────────────────────────────────
-- Generated by drizzle-kit (the `licences` table and its two indexes) and
-- hand-amended below the marker: the CHECKs, the family-unique index on the
-- licence number (an expression index — drizzle-kit does not model it, the
-- 0078 precedent), RLS (the tenant arm plus the 0041 `app.client_id` clause
-- on `client_id` — the 0077 shape), the notifications source vocabulary
-- widened with `licence-expiry`, and the post-migration probe (drizzle-kit
-- is blind to all of it; `bun run db:generate` afterwards reports "No schema
-- changes").
--
-- Additive: one new tenant-scoped table, empty at deploy. No data is
-- rewritten. No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- The RLS site-row proof (a site licence — null `client_id` — is invisible,
-- and its insert refused, under a stamped `app.client_id`) cannot run here:
-- the migrator is a superuser and bypasses RLS. It runs as the non-superuser
-- `wms_rls_probe` in test/client-isolation.spec.ts (story 1-6c arm).
--
-- Lock cost: re-adding `notifications_source_type_check` takes an ACCESS
-- EXCLUSIVE lock on `notifications` and scans it (the 0070/0071/0078
-- precedent).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'licences'
	) THEN
		RAISE EXCEPTION 'migration 0084: the licences table already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "licences" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid,
	"warehouse_id" uuid,
	"kind" text NOT NULL,
	"number" text NOT NULL,
	"valid_from" date,
	"valid_until" date,
	"note" text,
	"status" text DEFAULT 'active' NOT NULL,
	"upcoming_warned_on" date,
	"expired_warned_on" date,
	"open_warning_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE INDEX "licences_tenant_client_idx" ON "licences" USING btree ("tenant_id","client_id");--> statement-breakpoint
CREATE INDEX "licences_tenant_warehouse_idx" ON "licences" USING btree ("tenant_id","warehouse_id");
--> statement-breakpoint
-- ── hand-amended: the licences CHECKs (migration SQL only) ────────────────
-- Mirrored by `src/shared/primitives/licence.ts` (`LICENCE_KINDS`,
-- `licenceNumberProblem`, `LICENCE_NOTE_MAX`, `KINDS_REQUIRING_VALID_UNTIL`),
-- which the command answers as a named 400 first; the vocabularies are pinned
-- against these definitions by test/licences.spec.ts. Nullable columns say
-- IS NULL first (IMPLEMENTATION-GUIDE §3).
ALTER TABLE "licences" ADD CONSTRAINT "licences_kind_check" CHECK ("kind" IN (
	'drug-20b', 'drug-21b', 'drug-20g', 'ndps', 'fssai-registration', 'fssai-state', 'fssai-central'
));--> statement-breakpoint
-- A client licence (client set, a site optional — its premises) or a site licence (no client, a site).
ALTER TABLE "licences" ADD CONSTRAINT "licences_holder_check" CHECK (
	"client_id" IS NOT NULL OR "warehouse_id" IS NOT NULL
);--> statement-breakpoint
-- FSSAI: 14 digits; a registration starts with 2, a state or central licence with 1.
ALTER TABLE "licences" ADD CONSTRAINT "licences_fssai_number_check" CHECK (
	"kind" NOT IN ('fssai-registration', 'fssai-state', 'fssai-central')
	OR ("kind" = 'fssai-registration' AND "number" ~ '^2[0-9]{13}$')
	OR ("kind" IN ('fssai-state', 'fssai-central') AND "number" ~ '^1[0-9]{13}$')
);--> statement-breakpoint
-- Drug forms and NDPS: 1–50 of A–Z 0–9 space / . - — normalised (trimmed,
-- one space between words, upper-case).
ALTER TABLE "licences" ADD CONSTRAINT "licences_drug_number_check" CHECK (
	"kind" IN ('fssai-registration', 'fssai-state', 'fssai-central')
	OR ("number" ~ '^[A-Z0-9 /.-]{1,50}$' AND "number" = btrim("number") AND strpos("number", '  ') = 0)
);--> statement-breakpoint
ALTER TABLE "licences" ADD CONSTRAINT "licences_validity_order" CHECK (
	"valid_from" IS NULL OR "valid_until" IS NULL OR "valid_until" >= "valid_from"
);--> statement-breakpoint
-- FSSAI tiers and NDPS carry a fixed term; a drug form's date is optional (the retention due date).
ALTER TABLE "licences" ADD CONSTRAINT "licences_valid_until_required" CHECK (
	"kind" NOT IN ('ndps', 'fssai-registration', 'fssai-state', 'fssai-central') OR "valid_until" IS NOT NULL
);--> statement-breakpoint
ALTER TABLE "licences" ADD CONSTRAINT "licences_status_check" CHECK ("status" IN ('active', 'withdrawn'));--> statement-breakpoint
ALTER TABLE "licences" ADD CONSTRAINT "licences_note_length" CHECK (
	"note" IS NULL OR (char_length("note") BETWEEN 1 AND 200 AND "note" = btrim("note"))
);--> statement-breakpoint
-- ── hand-amended: the family-unique number (SQL only) ─────────────────────
-- A number is unique among a tenant's ACTIVE licences within its family: the
-- three FSSAI tiers are one family, each drug kind its own. A withdrawn
-- licence frees its number (a correction is a withdraw plus a new add). The
-- command catches it by name (`isUniqueViolationOn`) as 409 `licence-number-taken`.
CREATE UNIQUE INDEX "licences_family_number_unique" ON "licences" USING btree (
	"tenant_id",
	(CASE WHEN "kind" LIKE 'fssai-%' THEN 'fssai' ELSE "kind" END),
	"number"
) WHERE "status" = 'active';--> statement-breakpoint
-- ── hand-amended: RLS — the tenant arm plus the 0041 client clause ────────
-- A portal-stamped transaction (`app.client_id` set) sees only its own
-- client's licences — never a site licence (null `client_id` never equals a
-- stamp) — and cannot write one; an operator one (unset) sees the tenant's.
-- No portal route reads licences (decision 11) — this is defence in depth.
ALTER TABLE "licences" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "licences_tenant_isolation" ON "licences"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
-- ── hand-amended: the notifications source vocabulary, widened ───────────
-- Drop and re-add (the 0070/0071/0078 precedent): `licence-expiry` — one
-- entry per expiry warning (each raise a fresh warning id). Pinned against
-- `NOTIFICATION_SOURCE_TYPES` by test/notifications.spec.ts.
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_source_type_check";--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_source_type_check" CHECK ("source_type" IN (
	'stock-adjustment', 'count-variance', 'over-receipt', 'rejected-op',
	'reorder-breach', 'batch-alert', 'qc-hold', 'channel-sync', 'audit-export',
	'ledger-chain-break', 'qc-receipt', 'licence-expiry'
));--> statement-breakpoint
-- ── the post-migration assertion (the 0077/0083 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: a client licence with no site (head office), a
	-- premises licence (client + site), a site licence; every kind; a drug
	-- form with no dates; the same number active in two families; a
	-- withdrawn licence beside an active one with its number; the sweep's
	-- state columns; a `licence-expiry` notification.
	BEGIN
		INSERT INTO "licences" ("id","tenant_id","client_id","warehouse_id","kind","number","valid_from","valid_until","note","status")
		VALUES
			(gen_random_uuid(), t, c, NULL, 'fssai-state', '10012345678901', '2026-04-01', '2027-03-31', 'Head office', 'active'),
			(gen_random_uuid(), t, c, w, 'drug-20b', 'MH/PUN/20B 12', NULL, NULL, NULL, 'active'),
			(gen_random_uuid(), t, NULL, w, 'fssai-registration', '20012345678901', NULL, '2027-03-31', NULL, 'active'),
			(gen_random_uuid(), t, NULL, w, 'fssai-central', '10099999999999', NULL, '2027-03-31', NULL, 'active'),
			(gen_random_uuid(), t, NULL, w, 'drug-21b', 'MH/PUN/20B 12', NULL, NULL, NULL, 'active'),
			(gen_random_uuid(), t, NULL, w, 'drug-20g', 'X-1', '2026-01-01', '2026-01-01', NULL, 'active'),
			(gen_random_uuid(), t, NULL, w, 'ndps', 'NDPS.7-A', NULL, '2027-01-01', NULL, 'active'),
			(gen_random_uuid(), t, c, NULL, 'fssai-central', '10012345678901', NULL, '2026-03-31', NULL, 'withdrawn');
		UPDATE "licences" SET "upcoming_warned_on" = '2026-11-01', "expired_warned_on" = '2026-12-01', "open_warning_id" = gen_random_uuid()
		 WHERE "tenant_id" = t AND "kind" = 'ndps';
		INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","warehouse_id","summary","raised_at","surfaced_at")
		VALUES (gen_random_uuid(), t, 'licence-expiry', gen_random_uuid(), w, '{"kind":"ndps"}'::jsonb, now(), now());
		RAISE EXCEPTION USING ERRCODE = 'P0084', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0084: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0084' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'kind unknown', 'no holder', 'registration starting 1', 'state licence starting 2',
		'fssai 13 digits', 'fssai with letters', 'drug lower-case', 'drug untrimmed', 'drug double space',
		'drug 51 characters', 'drug bad character', 'until before from', 'ndps without until',
		'fssai without until', 'status unknown', 'note empty', 'note 201', 'note untrimmed',
		'fssai family duplicate', 'drug duplicate', 'source type unknown'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'kind unknown' THEN 'licences_kind_check'
			WHEN 'no holder' THEN 'licences_holder_check'
			WHEN 'registration starting 1' THEN 'licences_fssai_number_check'
			WHEN 'state licence starting 2' THEN 'licences_fssai_number_check'
			WHEN 'fssai 13 digits' THEN 'licences_fssai_number_check'
			WHEN 'fssai with letters' THEN 'licences_fssai_number_check'
			WHEN 'drug lower-case' THEN 'licences_drug_number_check'
			WHEN 'drug untrimmed' THEN 'licences_drug_number_check'
			WHEN 'drug double space' THEN 'licences_drug_number_check'
			WHEN 'drug 51 characters' THEN 'licences_drug_number_check'
			WHEN 'drug bad character' THEN 'licences_drug_number_check'
			WHEN 'until before from' THEN 'licences_validity_order'
			WHEN 'ndps without until' THEN 'licences_valid_until_required'
			WHEN 'fssai without until' THEN 'licences_valid_until_required'
			WHEN 'status unknown' THEN 'licences_status_check'
			WHEN 'note empty' THEN 'licences_note_length'
			WHEN 'note 201' THEN 'licences_note_length'
			WHEN 'note untrimmed' THEN 'licences_note_length'
			WHEN 'fssai family duplicate' THEN 'licences_family_number_unique'
			WHEN 'drug duplicate' THEN 'licences_family_number_unique'
			ELSE 'notifications_source_type_check'
		END;
		BEGIN
			CASE probe
				WHEN 'kind unknown' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'drug-20c', 'A1');
				WHEN 'no holder' THEN
					INSERT INTO "licences" ("id","tenant_id","kind","number") VALUES (gen_random_uuid(), t, 'drug-20b', 'A1');
				WHEN 'registration starting 1' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","valid_until") VALUES (gen_random_uuid(), t, c, 'fssai-registration', '10012345678901', '2027-01-01');
				WHEN 'state licence starting 2' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","valid_until") VALUES (gen_random_uuid(), t, c, 'fssai-state', '20012345678901', '2027-01-01');
				WHEN 'fssai 13 digits' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","valid_until") VALUES (gen_random_uuid(), t, c, 'fssai-central', '1001234567890', '2027-01-01');
				WHEN 'fssai with letters' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","valid_until") VALUES (gen_random_uuid(), t, c, 'fssai-central', '1001234567890A', '2027-01-01');
				WHEN 'drug lower-case' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'mh/20b');
				WHEN 'drug untrimmed' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'drug-20b', ' MH/20B');
				WHEN 'drug double space' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'MH  20B');
				WHEN 'drug 51 characters' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'drug-21b', repeat('A', 51));
				WHEN 'drug bad character' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'drug-20g', 'MH#20G');
				WHEN 'until before from' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","valid_from","valid_until") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'A2', '2027-01-02', '2027-01-01');
				WHEN 'ndps without until' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'ndps', 'A3');
				WHEN 'fssai without until' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number") VALUES (gen_random_uuid(), t, c, 'fssai-state', '10000000000004');
				WHEN 'status unknown' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","status") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'A4', 'expired');
				WHEN 'note empty' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","note") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'A5', '');
				WHEN 'note 201' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","note") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'A6', repeat('n', 201));
				WHEN 'note untrimmed' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","kind","number","note") VALUES (gen_random_uuid(), t, c, 'drug-20b', 'A7', 'note ');
				WHEN 'fssai family duplicate' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","warehouse_id","kind","number","valid_until")
					VALUES (gen_random_uuid(), t, c, NULL, 'fssai-state', '10000000000008', '2027-01-01'),
					       (gen_random_uuid(), t, NULL, w, 'fssai-central', '10000000000008', '2027-01-01');
				WHEN 'drug duplicate' THEN
					INSERT INTO "licences" ("id","tenant_id","client_id","warehouse_id","kind","number")
					VALUES (gen_random_uuid(), t, c, NULL, 'drug-20b', 'A9'), (gen_random_uuid(), t, NULL, w, 'drug-20b', 'A9');
				WHEN 'source type unknown' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'licence-expiries', gen_random_uuid(), '{}'::jsonb, now(), now());
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0084: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "licences" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "notifications" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0084: a probe row survived.';
	END IF;
END $$;
